//! Bench 807 — CLR verifier calibration GOAT (riir-ai Issue 964 C1).
//!
//! The first `sigmoid_calibration` consumer (substrate: katgpt-rs Issue 810).
//! `SigmoidProjectionVerifier`'s verdicts are bounded in (0,1) — Bench 284's
//! G2 measured ECE 0.0087 on a fixture whose ground truth was generated by
//! the SAME sigmoid. This gate upgrades that claim from "bounded" to
//! "calibrated" in the honest direction: it proves the calibration machinery
//! FIXES a drifted verifier and does NOT disturb a calibrated one.
//!
//! Gates:
//! - **G1** `g1_miscalibrated_fixture` — planted-transform fixture
//!   (`p_true = sigmoid(1.6·dot − 0.4)`, Issue 810's planted shape), train/
//!   test split. Calibrated ECE must land ≤ 0.05 AND beat the uncalibrated
//!   verdict on ECE, log-loss, and Brier (Report-the-Floor rule: also beat
//!   the base-rate floor on log-loss + Brier). Params must recover the
//!   planted transform.
//! - **G1b** `g1b_calibrated_fixture_no_harm` — the Bench-284 G2 fixture
//!   (ground truth = the verifier's own sigmoid). A refit on already-
//!   calibrated evidence must keep ECE within the 0.10 gate and within noise
//!   of the uncalibrated verdict.
//! - **G3** `g3_no_regression` — cold start is BIT-IDENTICAL to the raw
//!   verifier; a real refit never inverts pairwise verdict order; the CLR
//!   vote winner is unchanged under a near-identity refit (decision level).
//! - **G4** `g4_alloc_free_observe_apply` — steady-state observe + calibrated
//!   verify loop adds zero heap allocations (Issue-741 predicate: runs in dev
//!   AND `--release --features alloc_tracking`).
//!
//! Run with:
//! ```bash
//! cargo test --features clr_calibration --test bench_807_clr_calibration_goat -- --nocapture
//! ```
//!
//! # Sigmoid-only rule
//!
//! Every activation here is sigmoid. No softmax anywhere (CLR contract + the
//! user's `AGENTS.md` rule).

#![cfg(feature = "clr_calibration")]

use fastrand::Rng;
use katgpt_claim::clr::calibration::CalibratedVerifier;
use katgpt_claim::clr::{
    Claim, ClaimVerifier, ClrConfig, ClrScratch, DirectionVectorSource, FnClaimExtractor,
    SigmoidProjectionVerifier, Trajectory, clr_vote,
};
use katgpt_core::sigmoid_calibration::{brier_score, expected_calibration_error, log_loss};
use katgpt_core::simd::simd_dot_f32;

// ──────────────────────────────────────────────────────────────────────────
// Shared fixture helpers (bench_284 shapes, kept local so the two GOAT
// binaries stay independent).
// ──────────────────────────────────────────────────────────────────────────

/// Direction-vector pool backed by a flat `Vec<f32>` (bench_284's shape).
struct FlatDirections {
    dim: usize,
    vectors: Vec<f32>,
}

impl FlatDirections {
    fn from_rows(rows: &[&[f32]]) -> Self {
        let dim = rows[0].len();
        let mut vectors = Vec::with_capacity(rows.len() * dim);
        for r in rows {
            assert_eq!(r.len(), dim);
            vectors.extend_from_slice(r);
        }
        Self { dim, vectors }
    }
}

impl DirectionVectorSource for FlatDirections {
    fn direction(&self, idx: usize) -> &[f32] {
        &self.vectors[idx * self.dim..(idx + 1) * self.dim]
    }
    fn blake3(&self) -> [u8; 32] {
        *blake3::hash(bytemuck::cast_slice(&self.vectors)).as_bytes()
    }
    fn version(&self) -> u64 {
        1
    }
}

#[inline(always)]
fn sigmoid(x: f32) -> f32 {
    1.0 / (1.0 + (-x).exp())
}

const DIM: usize = 8;
const TRAIN_N: usize = 4096;
const TEST_N: usize = 4096;
const ECE_BINS: usize = 10;

/// One (embedding, raw_verdict, label) draw.
struct Draw {
    embedding: Vec<f32>,
    raw_verdict: f32,
    label: bool,
}

/// Build the single-direction pool (unit-norm, deterministic in `seed`).
/// Train/test splits share ONE direction pool — the verifier's directions
/// are fixed; only embeddings/labels differ across splits.
fn build_direction(seed: u64) -> FlatDirections {
    let mut rng = Rng::with_seed(seed);
    let mut dir = vec![0.0_f32; DIM];
    for d in dir.iter_mut() {
        *d = rng.f32() * 2.0 - 1.0;
    }
    let norm = dir.iter().map(|x| x * x).sum::<f32>().sqrt().max(1e-6);
    for d in dir.iter_mut() {
        *d /= norm;
    }
    FlatDirections::from_rows(&[dir.as_slice()])
}

/// Build `n` draws against `directions`. The label generator is injected so
/// the same harness serves both the miscalibrated fixture (planted
/// transform) and the calibrated one (identity transform). `seed` differs
/// between train and test splits so the splits are disjoint.
fn build_draws(
    seed: u64,
    n: usize,
    directions: &FlatDirections,
    label_of_dot: impl Fn(f32) -> f32 + Copy,
) -> Vec<Draw> {
    let mut rng = Rng::with_seed(seed);
    let mut draws = Vec::with_capacity(n);
    for _ in 0..n {
        // bench_284 G2's embedding generator: random entries, scale in
        // [0.5, 3.5] so dots span a wide range and exercise all bins.
        let scale = 0.5 + rng.f32() * 3.0;
        let embedding: Vec<f32> = (0..DIM).map(|_| (rng.f32() * 2.0 - 1.0) * scale).collect();
        let dot = simd_dot_f32(&embedding, directions.direction(0), DIM);
        let raw_verdict = sigmoid(dot);
        let p_true = label_of_dot(dot);
        let label = rng.f32() < p_true;
        draws.push(Draw {
            embedding,
            raw_verdict,
            label,
        });
    }
    draws
}

/// Verdict via the calibrated wrapper with `T = ()` pinned (the trait's
/// payload type only surfaces on `verify`, so bare `verify_embedding`
/// calls are ambiguous in test context).
#[inline]
fn cal_verdict(cal: &CalibratedVerifier<SigmoidProjectionVerifier<'_>>, emb: &[f32]) -> f32 {
    ClaimVerifier::<()>::verify_embedding(cal, emb, 0)
}

/// Raw verdict from the inner verifier with `T = ()` pinned.
#[inline]
fn raw_verdict(inner: &SigmoidProjectionVerifier<'_>, emb: &[f32]) -> f32 {
    ClaimVerifier::<()>::verify_embedding(inner, emb, 0)
}

// ══════════════════════════════════════════════════════════════════════════
// G1 — miscalibrated fixture: calibration fixes a drifted verifier
// ══════════════════════════════════════════════════════════════════════════

/// Planted transform (Issue 810's shape): the world acts on
/// `sigmoid(1.6·dot − 0.4)` while the verifier emits `sigmoid(dot)`.
const PLANTED_A: f32 = 1.6;
const PLANTED_B: f32 = -0.4;

#[test]
fn g1_miscalibrated_fixture() {
    let planted = |dot: f32| sigmoid(PLANTED_A.mul_add(dot, PLANTED_B));
    let directions = build_direction(0xC1A5_0001);
    let train = build_draws(0xC1A5_0002, TRAIN_N, &directions, planted);
    let test = build_draws(0xC1A5_0003, TEST_N, &directions, planted);

    // Fit: observe (raw verdict, outcome) at the harness points, refit.
    let inner = SigmoidProjectionVerifier::new(&directions, DIM);
    let mut calibrated = CalibratedVerifier::new(inner, TRAIN_N, TRAIN_N / 4);
    for d in &train {
        calibrated.observe(d.raw_verdict, d.label);
    }
    assert!(
        calibrated.refit(),
        "planted fixture must move the parameters"
    );

    let (t, b) = calibrated.params();

    // Evaluate on the held-out test split.
    let mut raw_ps = Vec::with_capacity(TEST_N);
    let mut cal_ps = Vec::with_capacity(TEST_N);
    let mut ys = Vec::with_capacity(TEST_N);
    for d in &test {
        let cal_p = cal_verdict(&calibrated, &d.embedding);
        raw_ps.push(d.raw_verdict);
        cal_ps.push(cal_p);
        ys.push(f32::from(d.label));
    }

    let ece_raw = expected_calibration_error(&raw_ps, &ys, ECE_BINS);
    let ece_cal = expected_calibration_error(&cal_ps, &ys, ECE_BINS);
    let ll_raw = log_loss(&raw_ps, &ys);
    let ll_cal = log_loss(&cal_ps, &ys);
    let br_raw = brier_score(&raw_ps, &ys);
    let br_cal = brier_score(&cal_ps, &ys);

    // Base-rate floor (Report-the-Floor rule): predict the train positive
    // rate for every test point.
    let base_rate = train.iter().map(|d| f32::from(d.label)).sum::<f32>() / TRAIN_N as f32;
    let floor_ps = vec![base_rate; TEST_N];
    let ll_floor = log_loss(&floor_ps, &ys);
    let br_floor = brier_score(&floor_ps, &ys);

    eprintln!("──────── G1: miscalibrated fixture (planted 1.6·dot − 0.4) ────────");
    eprintln!("train/test    : {TRAIN_N}/{TEST_N}, bins {ECE_BINS}");
    eprintln!(
        "recovered     : (T, b) = ({t:.3}, {b:.3})  (planted ({:.3}, {:.3}))",
        1.0 / PLANTED_A,
        -PLANTED_B / PLANTED_A
    );
    eprintln!("ECE     raw → cal: {ece_raw:.4} → {ece_cal:.4} (target ≤ 0.05)");
    eprintln!("logloss raw → cal: {ll_raw:.4} → {ll_cal:.4} (floor {ll_floor:.4})");
    eprintln!("brier   raw → cal: {br_raw:.4} → {br_cal:.4} (floor {br_floor:.4})");

    assert!(
        ece_cal <= 0.05,
        "G1 FAILED: calibrated ECE {ece_cal:.4} > 0.05"
    );
    assert!(
        ece_cal < ece_raw,
        "G1 FAILED: calibrated ECE {ece_cal:.4} not < raw {ece_raw:.4}"
    );
    assert!(
        ll_cal < ll_raw && ll_cal < ll_floor,
        "G1 FAILED: log-loss cal {ll_cal:.4} must beat raw {ll_raw:.4} and floor {ll_floor:.4}"
    );
    assert!(
        br_cal < br_raw && br_cal < br_floor,
        "G1 FAILED: Brier cal {br_cal:.4} must beat raw {br_raw:.4} and floor {br_floor:.4}"
    );
    // Planted-transform recovery within 0.05 (Issue 810 recovered at ~0.002).
    let (t_planted, b_planted) = (1.0_f32 / PLANTED_A, -PLANTED_B / PLANTED_A);
    assert!(
        (t - t_planted).abs() < 0.05 && (b - b_planted).abs() < 0.05,
        "G1 FAILED: planted-transform recovery ({t:.3}, {b:.3}) vs ({t_planted:.3}, {b_planted:.3})"
    );
    eprintln!("G1 PASS ✅");
}

// ══════════════════════════════════════════════════════════════════════════
// G1b — calibrated fixture (Bench 284 G2 shape): no harm
// ══════════════════════════════════════════════════════════════════════════

#[test]
fn g1b_calibrated_fixture_no_harm() {
    let identity = |dot: f32| sigmoid(dot);
    let directions = build_direction(0xBEEF_0001);
    let train = build_draws(0xBEEF_0002, TRAIN_N, &directions, identity);
    let test = build_draws(0xBEEF_0003, TEST_N, &directions, identity);

    let inner = SigmoidProjectionVerifier::new(&directions, DIM);
    let mut calibrated = CalibratedVerifier::new(inner, TRAIN_N, TRAIN_N / 4);
    for d in &train {
        calibrated.observe(d.raw_verdict, d.label);
    }
    let moved = calibrated.refit();
    let (t, b) = calibrated.params();

    let mut raw_ps = Vec::with_capacity(TEST_N);
    let mut cal_ps = Vec::with_capacity(TEST_N);
    let mut ys = Vec::with_capacity(TEST_N);
    for d in &test {
        let cal_p = cal_verdict(&calibrated, &d.embedding);
        raw_ps.push(d.raw_verdict);
        cal_ps.push(cal_p);
        ys.push(f32::from(d.label));
    }
    let ece_raw = expected_calibration_error(&raw_ps, &ys, ECE_BINS);
    let ece_cal = expected_calibration_error(&cal_ps, &ys, ECE_BINS);
    let ll_delta = log_loss(&cal_ps, &ys) - log_loss(&raw_ps, &ys);
    let br_delta = brier_score(&cal_ps, &ys) - brier_score(&raw_ps, &ys);

    eprintln!("──────── G1b: calibrated fixture (Bench 284 G2 shape) ────────");
    eprintln!("refit moved params: {moved}; landed (T, b) = ({t:.4}, {b:.4}) — near identity");
    eprintln!(
        "ECE raw → cal: {ece_raw:.4} → {ece_cal:.4} (Δ {:+.4})",
        ece_cal - ece_raw
    );
    eprintln!("logloss Δ {ll_delta:+.4}, brier Δ {br_delta:+.4}");
    eprintln!(
        "no-harm band : |ΔECE| ≤ 0.005 (bin sampling noise at n={TEST_N}, 10 bins) + the standing 0.10 gate — the claim is 'within noise of raw', NOT improvement (there is nothing to fix)"
    );

    assert!(
        ece_cal <= 0.10,
        "G1b FAILED: calibrated ECE {ece_cal:.4} exceeds the standing 0.10 gate"
    );
    assert!(
        (ece_cal - ece_raw).abs() <= 0.005,
        "G1b FAILED: calibrated ECE {ece_cal:.4} moved {:+.4} from raw {ece_raw:.4} — outside the ±0.005 sampling-noise band",
        ece_cal - ece_raw
    );
    eprintln!("G1b PASS ✅");
}

// ══════════════════════════════════════════════════════════════════════════
// G3 — no regression: bit-identity, monotonicity, decision stability
// ══════════════════════════════════════════════════════════════════════════

#[test]
fn g3_no_regression() {
    // ── (a) cold start: bit-identical verdicts ────────────────────────────
    let identity = |dot: f32| sigmoid(dot);
    let directions = build_direction(0x51D3_0001);
    let draws = build_draws(0x51D3_0002, 512, &directions, identity);
    let inner = SigmoidProjectionVerifier::new(&directions, DIM);
    let calibrated = CalibratedVerifier::new(inner, 64, 16);
    for (i, d) in draws.iter().enumerate() {
        let raw = raw_verdict(calibrated.inner(), &d.embedding);
        let cal = cal_verdict(&calibrated, &d.embedding);
        assert_eq!(
            raw.to_bits(),
            cal.to_bits(),
            "cold start must be exact (draw {i})"
        );
    }
    eprintln!(
        "──────── G3a: cold-start bit-identity over {} verdicts ────────",
        draws.len()
    );

    // ── (b) real refit never inverts pairwise order ──────────────────────
    let planted = |dot: f32| sigmoid(PLANTED_A.mul_add(dot, PLANTED_B));
    let train = build_draws(0xC1A5_0002, TRAIN_N, &directions, planted);
    let test = build_draws(0xC1A5_0003, TEST_N, &directions, planted);
    let inner2 = SigmoidProjectionVerifier::new(&directions, DIM);
    let mut fitted = CalibratedVerifier::new(inner2, TRAIN_N, TRAIN_N / 4);
    for d in &train {
        fitted.observe(d.raw_verdict, d.label);
    }
    assert!(fitted.refit());

    let mut raws: Vec<f32> = Vec::with_capacity(TEST_N);
    let mut cals: Vec<f32> = Vec::with_capacity(TEST_N);
    for d in &test {
        raws.push(d.raw_verdict);
        cals.push(cal_verdict(&fitted, &d.embedding));
    }
    // Monotone map: sorted-by-raw must be non-decreasing in cal.
    let mut idx: Vec<usize> = (0..TEST_N).collect();
    idx.sort_by(|&a, &b| raws[a].total_cmp(&raws[b]));
    let mut inversions = 0usize;
    for w in idx.windows(2) {
        if cals[w[1]] < cals[w[0]] {
            inversions += 1;
        }
    }
    eprintln!("──────── G3b: pairwise order after real refit — {inversions} inversions ────────");
    assert_eq!(
        inversions, 0,
        "G3b FAILED: monotone calibration inverted {inversions} verdict pairs"
    );

    // ── (c) decision level: vote winner stable under near-identity refit ─
    // Refit on CALIBRATED evidence (the G1b corpus) — the params land near
    // identity, and the vote winner must not move on any seed of a
    // bench_284-G1-shaped suite.
    let cal_train = build_draws(0xBEEF_0002, TRAIN_N, &directions, identity);
    const SEEDS: usize = 25;
    let config = ClrConfig {
        k: 50,
        m: 5,
        embedding_dim: 8,
        ..ClrConfig::default()
    };
    let mut scratch = ClrScratch::new(config.k, config.m, 8);
    let mut moved_winner = 0usize;
    let mut first_params = None;
    for seed in 0..SEEDS as u64 {
        let (trajs, g1_dirs) = build_g1_suite_local(seed);
        let raw_verifier = SigmoidProjectionVerifier::new(&g1_dirs, 8);
        let inner_for_cal = SigmoidProjectionVerifier::new(&g1_dirs, 8);
        let mut cal = CalibratedVerifier::new(inner_for_cal, TRAIN_N, TRAIN_N / 4);
        for d in &cal_train {
            cal.observe(d.raw_verdict, d.label);
        }
        assert!(cal.refit());
        if first_params.is_none() {
            first_params = Some(cal.params());
        }

        let pick_raw = vote_pick(&trajs, &config, &mut scratch, &raw_verifier);
        let pick_cal = vote_pick(&trajs, &config, &mut scratch, &cal);
        if pick_raw != pick_cal {
            moved_winner += 1;
        }
    }
    let (t_ni, b_ni) = first_params.expect("at least one seed");
    eprintln!(
        "──────── G3c: near-identity refit (T, b) = ({t_ni:.4}, {b_ni:.4}); {moved_winner}/{SEEDS} seeds with a moved winner (target 0) ────────"
    );
    assert_eq!(
        moved_winner, 0,
        "G3c FAILED: near-identity refit moved the vote winner on {moved_winner}/{SEEDS} seeds"
    );
    eprintln!("G3 PASS ✅");
}

/// bench_284's `build_g1_suite`, kept local (5 clusters × 10 trajectories,
/// M=5, dim=8, cluster 4 ground-truth-highest).
fn build_g1_suite_local(seed: u64) -> (Vec<Trajectory<u8>>, FlatDirections) {
    let mut rng = Rng::with_seed(seed);
    let mut dir_rows: Vec<Vec<f32>> = Vec::with_capacity(5);
    for _ in 0..5 {
        let mut v: Vec<f32> = (0..8).map(|_| rng.f32() * 2.0 - 1.0).collect();
        let norm = v.iter().map(|x| x * x).sum::<f32>().sqrt().max(1e-6);
        for x in v.iter_mut() {
            *x /= norm;
        }
        dir_rows.push(v);
    }
    let dir_refs: Vec<&[f32]> = dir_rows.iter().map(|v| v.as_slice()).collect();
    let directions = FlatDirections::from_rows(&dir_refs);

    let mut trajectories: Vec<Trajectory<u8>> = Vec::with_capacity(50);
    for cluster_id in 0..5u8 {
        let baseline = 1.0_f32 + 0.05 * cluster_id as f32;
        for member in 0..10 {
            let is_flawed_member = member == 0;
            let m_flaw = rng.usize(0..5);
            let mut claims: Vec<Claim<u8>> = Vec::with_capacity(5);
            for m in 0..5 {
                let dir = directions.direction(m);
                let mut emb = vec![0.0_f32; 8];
                for d in 0..8 {
                    let n = (rng.f32() * 2.0 - 1.0) * 0.05;
                    emb[d] = baseline * dir[d] + n;
                }
                if is_flawed_member && m == m_flaw {
                    let mut perturb: Vec<f32> = (0..8).map(|_| rng.f32() * 2.0 - 1.0).collect();
                    let dot_p = simd_dot_f32(&perturb, dir, 8);
                    for d in 0..8 {
                        perturb[d] -= dot_p * dir[d];
                    }
                    let pn = perturb.iter().map(|x| x * x).sum::<f32>().sqrt().max(1e-6);
                    for v in perturb.iter_mut() {
                        *v = *v / pn * baseline;
                    }
                    emb = perturb;
                }
                claims.push(Claim {
                    embedding: emb,
                    payload: cluster_id,
                });
            }
            trajectories.push(Trajectory {
                outcome: cluster_id,
                tokens_or_steps: 100 + member,
                claims,
                log_probs: None,
            });
        }
    }
    (trajectories, directions)
}

fn vote_pick<V: ClaimVerifier<u8>>(
    trajectories: &[Trajectory<u8>],
    config: &ClrConfig,
    scratch: &mut ClrScratch,
    verifier: &V,
) -> u8 {
    let extractor = FnClaimExtractor::new(5, |t: &Trajectory<u8>| t.claims.clone());
    let outcome_eq = |a: &u8, b: &u8| a == b;
    let result = clr_vote(
        trajectories,
        &extractor,
        verifier,
        config,
        &outcome_eq,
        scratch,
    );
    result.winner.outcome
}

// ══════════════════════════════════════════════════════════════════════════
// G4 — alloc-free observe + calibrated verify
// ══════════════════════════════════════════════════════════════════════════

// Issue 721 T3: install the tracking allocator in THIS test binary via the
// shared module (the root lib no longer registers a library-level
// allocator). The module self-gates its #[global_allocator] on the
// Issue-741 predicate, so including it unconditionally is inert at
// release-default.
#[path = "common/alloc_tracking.rs"]
mod alloc_tracking;

/// Liveness sentinel (Issue 682): fail the gate if the TrackingAllocator is
/// not actually installed — an alloc gate over a dead counter is vacuous.
#[cfg(any(debug_assertions, feature = "alloc_tracking"))]
fn assert_alloc_tracking_live() {
    katgpt_core::alloc::reset_alloc_stats();
    let _probe: Vec<u8> = vec![0u8; 64];
    let (count, _) = katgpt_core::alloc::get_alloc_stats();
    assert!(
        count >= 1,
        "TrackingAllocator not installed in this binary — alloc gate is VACUOUS (Issue 682)"
    );
    katgpt_core::alloc::reset_alloc_stats();
}

// Issue 741 predicate: runs in dev AND
// `--release --features clr_calibration,alloc_tracking`; compiles away at
// release-default instead of breaking the harness (the house convention).
#[cfg(any(debug_assertions, feature = "alloc_tracking"))]
#[test]
fn g4_alloc_free_observe_apply() {
    use katgpt_core::alloc::{get_alloc_stats, reset_alloc_stats};

    let identity = |dot: f32| sigmoid(dot);
    let directions = build_direction(0xA11C_0001);
    let draws = build_draws(0xA11C_0002, 2048, &directions, identity);
    let inner = SigmoidProjectionVerifier::new(&directions, DIM);
    let mut calibrated = CalibratedVerifier::new(inner, 1024, 256);
    // Warm the evidence window to capacity so the loop exercises the FIFO
    // ring-write path, and fit so `apply` exercises the full calibrated path
    // (not just the identity fast path).
    for d in draws.iter().take(1024) {
        calibrated.observe(d.raw_verdict, d.label);
    }
    assert!(calibrated.refit());

    // All data built outside the measurement window.
    let embeddings: Vec<&[f32]> = draws.iter().map(|d| d.embedding.as_slice()).collect();
    let labels: Vec<bool> = draws.iter().map(|d| d.label).collect();
    let verdicts: Vec<f32> = draws.iter().map(|d| d.raw_verdict).collect();

    assert_alloc_tracking_live();
    reset_alloc_stats();
    let before = get_alloc_stats().0;
    let mut sink = 0.0f32;
    for i in 0..2048 {
        calibrated.observe(verdicts[i], labels[i]);
        sink += cal_verdict(&calibrated, embeddings[i]);
    }
    let after = get_alloc_stats().0;
    let delta = after - before;
    eprintln!(
        "──────── G4: 2048 × (observe + calibrated verify) — {delta} allocs (target 0); sink {sink:.3} ────────"
    );
    std::hint::black_box(sink);
    assert_eq!(
        delta, 0,
        "G4 FAILED: {delta} allocations on the observe+apply path"
    );
    eprintln!("G4 PASS ✅");
}
